import { render } from 'preact';
import { getStorageItems, setStorageItems } from '../../shared/chromeApi';
import { ContentAds } from './interfaces';

import animal1 from './assets/animal1.svg';
import animal2 from './assets/animal2.svg';
import animal3 from './assets/animal3.svg';
import animal4 from './assets/animal4.svg';
import animal5 from './assets/animal5.svg';

import { getRandomNumberInBetween } from './components/shared/utils';
import { toRuntimeUrl } from '../shared/utils';

export const renderPreact = (vnode, $parent: Element = document.querySelector('body'), dataOhId?: string, shouldPrepend?: boolean) => {
  const $container = document.createElement('div');
  $container.style.display = 'contents'

  if (dataOhId) {
    $container.dataset['ohId'] = dataOhId;
  }
  $parent[shouldPrepend ? 'prepend' : 'appendChild']($container);
  return render(vnode, $container);
};

export const isDarkMode = () =>
  window.getComputedStyle(document.body ,null).getPropertyValue('background-color') !== 'rgb(255, 255, 255)';

export const setTheme = (variables) => {
  Object.keys(variables).forEach((property) => {
    document.documentElement.style
      .setProperty(property, variables[property]);
  });
}

export const getContentAds = async () =>
  getStorageItems<{ contentAds: ContentAds }>(['contentAds']);

export const updateContentAds = async (params: ContentAds) =>
  getContentAds()
    .then(({ contentAds }) => {
      console.log('updateContentAds', contentAds);

      setStorageItems({ contentAds: {...contentAds, ...params } });
    })
    .catch((err) => {
      console.error('updateContentAds', err);
    });

export const isElementInViewport = (el, margin) => {
  const rect = el.getBoundingClientRect();

  return (
    rect.bottom > 0 &&
    rect.right > 0 &&
    rect.left - margin <
    (window.innerWidth ||
      document.documentElement.clientWidth) /* or $(window).width() */ &&
    rect.top - margin <
    (window.innerHeight ||
      document.documentElement.clientHeight) /* or $(window).height() */
  );
};

const animals = [animal1, animal2, animal3, animal4, animal5];

export const getRandomAnimalImage = (): string => {
  const animalNum = getRandomNumberInBetween(0, 4);
  return toRuntimeUrl(animals[animalNum]);
};
