import Close from '@material-ui/icons/Close';
import { FunctionalComponent} from 'preact';
import { forwardRef } from 'preact/compat';

import styles from './styles.module.scss';
import useOnClickOutside from '../../../../../shared/hooks/useOutsideClick';
import { useRef } from 'preact/hooks';

interface Props {
  onClose: (e: MouseEvent) => unknown,
  className?: string,
  children: any,
  style?: any,
  arrow: 'top' | 'bottom' | 'right' | 'left'
}

const Tooltip: FunctionalComponent<Props> = forwardRef(({ onClose, arrow, className, style, children }: Props) => {
  const ref = useRef<HTMLDivElement>();
  useOnClickOutside(ref, onClose);

  return (
    <div className={`${styles.tooltipOverlay} ${className || ''}`} style={style}>
      <div ref={ref} className={styles.tooltip}>
        <div className={`${styles.arrow} ${styles[arrow]}`} />
        <div className={styles.closeButton} onClick={onClose}>
          <Close className={styles.closeIcon} />
        </div>
        <p>{children}</p>
      </div>
    </div>
  );
});

export default Tooltip;
