import { FunctionalComponent } from 'preact';
import { useEffect, useRef, useState } from 'preact/compat';

import { toRuntimeUrl } from '../../../shared/utils';
import { AdTile } from '../../../../newtab/features/tiles/slice/types';

import RewardTooltip from '../shared/RewardTooltip';
import ContextMenu from '../shared/ContextMenu';
import { getRandomNumberInBetween, openUrl, trackGain } from '../shared/utils';

import styles from './styles.module.scss';
import logoTinyText from './logo-tiny-text.png';
import { FeatureFlags } from '../../../../newtab/features/user/slice/types';

interface TileProps {
  ad: AdTile,
  onClick: (evt) => void,
}

const Tile: FunctionalComponent<TileProps> = ({ ad, onClick }: TileProps) => (
  <a
    href={ad.click_url}
    className={styles.tile}
    data-testid='tile'
    onClick={onClick}
    target="_blank"
    rel="noreferrer">
    <img src={ad.image_url} alt={ad.title} width={50} height={50} />
    <img className={styles.adImpression} src={ad.impression_url} alt='' />
  </a>
);

interface Props {
  list: AdTile[],
  style?: any,
  featureFlags: FeatureFlags,
}

const Tiles: FunctionalComponent<Props> = ({ list, style, featureFlags }: Props) => {
  const [state, setState] = useState(null);

  const handleClick = (evt, ad) => {
    evt.preventDefault();
    setTimeout(() => {
      openUrl(ad.click_url);
      setState(null);
    }, 700);

    if (state) return null;

    const gain = getRandomNumberInBetween(15, 50);
    trackGain({
      gain, revenue: 0.1, provider: 'adMarketplace', productId: 'CONTENT_TILE_AD',
      eventName: 'Clicked_content_tile'
    });
    setState({ gain, ad });
  };

  const $refContainer = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (featureFlags.GOOGLE_ADS_IMPRESSIONS) {
      chrome.runtime.sendMessage({
        type: 'trackAnalytics',
        events: [
          {
            variant: 'event',
            payload: ['Google ads impression', { type: 'tiles', value: list.length, category: 'Ads' }],
          },
        ],
      });
    }

    const callback = () => {
      const absolutePositon = 187;
      const scrollTop = document.documentElement.scrollTop || document.body.scrollTop;
      if (scrollTop > absolutePositon - 70) {
        $refContainer.current.style.position = 'fixed';
        $refContainer.current.style.top = '70px';
      } else {
        $refContainer.current.style.position = null;
        $refContainer.current.style.top = null;
      }
    };

    window.addEventListener('scroll', callback, { passive: true });
    return () => {
      window.removeEventListener('scroll', callback);
    };
  }, []);

  return (
    <div ref={$refContainer} className={styles.container} style={style} data-testid="oh-tiles">
      <div className={styles.tilesList} data-testid="list">
        {list.map((ad) => (
          <div key={ad.id} style={{ position: 'relative' }}>
            {state?.ad === ad && (
              <RewardTooltip gain={state.gain} style={{ left: 60, top: -10 }} />
            )}
            <Tile ad={ad} onClick={(evt) => handleClick(evt, ad)} />
          </div>
        ))}
      </div>

      <div className={styles.logo}>
        <img src={toRuntimeUrl(logoTinyText)} alt='OceanHero' width={40} />
        <div className={styles.logoLabel}>ads</div>

        <ContextMenu
          className={styles.contextMenu}
          variant="tiles"
          style={{ position: 'absolute', right: -30, top: 0 }}
        />
      </div>
    </div>
  );
};

export default Tiles;