import { FunctionalComponent, JSX } from 'preact';
import { useState, useEffect, useRef } from 'preact/compat';

import { FeatureFlags } from '../../../../newtab/features/user/slice/types';
import { AdMarketplaceLongTailData } from '../../../../newtab/features/searchForm/slice/types';
import RewardTooltip from '../shared/RewardTooltip';
import { getRandomNumberInBetween, openUrl, trackGain } from '../shared/utils';
import ContextMenu from '../shared/ContextMenu';
import { getContentAds, updateContentAds } from '../../utils';
import Tooltip from '../shared/Tooltip';
import styles from './styles.module.scss';

interface Props {
  style?: JSX.CSSProperties,
  data: AdMarketplaceLongTailData,
  featureFlags: FeatureFlags
}

const Sidebar: FunctionalComponent<Props> = ({ data, style, featureFlags }: Props) => {
  const [state, setState] = useState(null);

  const handleClick = (evt, ad) => {
    evt.preventDefault();
    setTimeout(() => {
      openUrl(ad.clickurl);
      setState(null);
    }, 700);

    if (state) return null;

    const gain = getRandomNumberInBetween(15, 50);
    trackGain({
      gain, revenue: 0.1, provider: 'adMarketplace', productId: 'CONTENT_SIDEBAR_AD',
      eventName: 'Clicked_content_sidebar_ad'
    });
    setState({ gain, ad });
  };

  const $ref = useRef<HTMLDivElement>(null);
  // const [isVisible, setVisible] = useState(null);

  const [showTooltip, setTooltip] = useState(false);
  const handleClose = () => {
    updateContentAds({ isSidebarDiscovered: true });
    setTooltip(false);
  };

  useEffect(() => {
    if (featureFlags.GOOGLE_ADS_IMPRESSIONS) {
      chrome.runtime.sendMessage({
        type: 'trackAnalytics',
        events: [
          {
            variant: 'event',
            payload: ['Google ads impression', { type: 'sidebar', value: Number(data?.count), category: 'Ads' }],
          },
        ],
      });
    }

    getContentAds().then(({ contentAds }) => {
      setTooltip(!contentAds?.isSidebarDiscovered);
    }).catch((err) => {
      console.error('Tiles getStorageItems', err);
    });

    // const check = () => {
    //   const isVisible = isElementInViewport($ref.current, -200);
    //   if (isVisible) setVisible(true);
    //
    //   return isVisible;
    // }
    //
    // if (!check()) {
    //   const callback = () => {
    //     if (check()) {
    //       window.removeEventListener('scroll', callback);
    //     }
    //   }
    //   window.addEventListener('scroll', callback, { passive: true });
    //   return () => {
    //     window.removeEventListener('scroll', callback);
    //   };
    // }
  }, []);

  return (
    <div ref={$ref} className={`${styles.container} ${styles.enter}`} style={style} data-testid="oh-sidebar">
      {showTooltip && (
        <Tooltip
          arrow="right"
          style={{ top: '-15px', left: '20px', transform: 'translateX(-100%)' }}
          onClose={handleClose}
        >Help us protect the oceans with these ads 🐢</Tooltip>
      )}

      <div style={{ position: 'relative', display: 'flex' }}>
        <h2 className={styles.title}>Ads by OceanHero</h2>

        <ContextMenu size="small" variant="sidebar" style={{ top: -4, left: -2, }} />
      </div>

      {data.adlistings.listing.map((ad) => (
        <a
          href={ad.clickurl}
          target="_blank"
          rel="noreferrer"
          key={ad.adId}
          className={styles.ad}
          onClick={(evt) => handleClick(evt, ad)}
        >
          {state?.ad === ad && (
            <RewardTooltip hideArrow gain={state.gain} style={{ left: -15, top: 0, transform: 'translateX(-100%)' }} />
          )}

          <div className={styles.adUrl}>{ad.displayurl}</div>

          <div className={styles.urlTitle}>{ad.title}</div>

          <div className={styles.urlDescription}>{ad.description}</div>
        </a>
      ))}
    </div>
  );
};

export default Sidebar;