import { FeatureFlags } from '../../../../newtab/features/user/slice/types';
import { renderPreact } from '../../utils';

import Tiles from '.';
import { requestAffinityTiles } from './api';

const renderTiles = async (query: string, featureFlags: FeatureFlags) => {
  const tiles = await requestAffinityTiles(query);

  if (!tiles?.length) return null;
  // if (!matchedTiles.length) return null;

  renderPreact(<Tiles featureFlags={featureFlags} list={tiles} />, undefined, 'tiles');
};

export default renderTiles;